INSERT INTO `tasks`(`id`,`type`,`duration`,`duration_code`,`title`,`description`,`reward_text`,`reward_id_list`,`cash_reward`,`exp_reward`,`reward_method`,`reward_points`,`reward_point_type`,`min_level`,`max_level`,`level_spread`,`min_players`,`max_players`,`repeatable`,`faction_reward`,`completion_emote`,`replay_timer_group`,`replay_timer_seconds`,`request_timer_group`,`request_timer_seconds`,`dz_template_id`,`lock_activity_id`,`faction_amount`,`enabled`)SELECT e.`id`,e.`type`,e.`duration`,e.`duration_code`,e.`title`,e.`description`,e.`reward_text`,e.`reward_id_list`,e.`cash_reward`,e.`exp_reward`,e.`reward_method`,e.`reward_points`,e.`reward_point_type`,e.`min_level`,e.`max_level`,e.`level_spread`,e.`min_players`,e.`max_players`,e.`repeatable`,e.`faction_reward`,e.`completion_emote`,e.`replay_timer_group`,e.`replay_timer_seconds`,e.`request_timer_group`,e.`request_timer_seconds`,e.`dz_template_id`,e.`lock_activity_id`,e.`faction_amount`,e.`enabled` FROM `_mer_tasks` e WHERE @mer_ok=1 AND NOT EXISTS(SELECT 1 FROM `tasks` a WHERE a.`id`<=>e.`id`);
