INSERT INTO `dynamic_zone_templates`(`id`,`zone_id`,`zone_version`,`name`,`min_players`,`max_players`,`duration_seconds`,`dz_switch_id`,`compass_zone_id`,`compass_x`,`compass_y`,`compass_z`,`return_zone_id`,`return_x`,`return_y`,`return_z`,`return_h`,`override_zone_in`,`zone_in_x`,`zone_in_y`,`zone_in_z`,`zone_in_h`)SELECT e.`id`,e.`zone_id`,e.`zone_version`,e.`name`,e.`min_players`,e.`max_players`,e.`duration_seconds`,e.`dz_switch_id`,e.`compass_zone_id`,e.`compass_x`,e.`compass_y`,e.`compass_z`,e.`return_zone_id`,e.`return_x`,e.`return_y`,e.`return_z`,e.`return_h`,e.`override_zone_in`,e.`zone_in_x`,e.`zone_in_y`,e.`zone_in_z`,e.`zone_in_h` FROM `_mer_dynamic_zone_templates` e WHERE @mer_ok=1 AND NOT EXISTS(SELECT 1 FROM `dynamic_zone_templates` a WHERE a.`id`<=>e.`id`);
INSERT INTO `shared_task_average_level_policies`(`task_id`,`minimum_average_level`,`enabled`)SELECT e.`task_id`,e.`minimum_average_level`,e.`enabled` FROM `_mer_shared_task_average_level_policies` e WHERE @mer_ok=1 AND NOT EXISTS(SELECT 1 FROM `shared_task_average_level_policies` a WHERE a.`task_id`<=>e.`task_id`);
INSERT INTO `reward_sets`(`reward_set_id`,`title`,`enabled`)SELECT e.`reward_set_id`,e.`title`,e.`enabled` FROM `_mer_reward_sets` e WHERE @mer_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_sets` a WHERE a.`reward_set_id`<=>e.`reward_set_id`);
